// True when the JSON number literal denotes an exact integer, e.g. "1000",
// "1000.0", "1e3", "1500e-3".
function isIntegralLiteral(source) {
  const m = NUMBER_LITERAL_RE.exec(source);
  if (!m) return false;
  const frac = m[2] || '';
